@Override
    public String getStats()
    {
        final ICacheStats[] stats = getStatistics();
        if ( stats == null )
        {
            return "NONE";
        }

        // force the array elements into a string.
        final StringBuilder buf = new StringBuilder();
        Stream.of(stats).forEach(stat -> {
            buf.append( "\n---------------------------\n" );
            buf.append( stat );
        });
        return buf.toString();
    }

