@Override
    public <T> byte[] serialize(final T obj)
        throws IOException
    {
        final ByteArrayOutputStream baos = new ByteArrayOutputStream();

        try (ObjectOutputStream oos = new ObjectOutputStream(baos))
        {
            oos.writeUnshared(obj);
        }

        return baos.toByteArray();
    }

